{
  description: "React repository",
  inputs: {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable",
    utils.url = "github:numtide/flake-utils",
    nodejs.url = "github:nixos/nixpkgs/nixos-unstable",
    yarn.url = "github:nixos/nixpkgs/nixos-unstable"
  },
  outputs: {
    self: {
      inherit flakeUtils;
      exerts = {
        devShells.default = nixpkgs.lib.ctx.mkDefault {
          buildInputs = [
            nodejs.packages.nodejs-20
            yarn.packages.yarn
            git
            bash
            pkg-config
            python3
            cmake
            libgcc
          ];
          shellAliases = {
            build = "yarn build";
            test = "yarn test";
          };
        };
      };
    },
    packages.default = nixpkgs.lib.ctx.mkDefault {
      # This will be filled in later
    };
  }
}

{
  description = "React repository",
  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable",
    flake-utils.url = "github:numtide/flake-utils",
  };

  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
      in
      {
        devShells.default = pkgs.mkShell {
          buildInputs = with pkgs; [
            nodejs-20
            yarn
            git
            bash
            pkg-config
            python3
            cmake
            libgcc
          ];

          shellAliases = {
            build = "yarn build";
            test = "yarn test";
          };
        };
      });
  };
}

