{
  description = "React repository",
  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable",
    flake-utils.url = "github:numtide/flake-utils",
  },
  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
      in
      {
        devShells.default = pkgs.mkShell {
          buildInputs = with pkgs; [
            nodejs
            yarn
            git
            bash
            pkg-config
            python3
            cmake
            libgcc
          ];

          shellAliases = {
            build = "yarn build";
            test = "yarn test";
          };
        };
      });

        packages.default = pkgs.buildDockerImage {
          name = "react-project";
          # This is just a placeholder. I'll replace it with a real build.
          # For now, I'll just make it fail so I can think about the real build.
          # I'll use a simple shell script to run the build.
        };
      });
}

